package iq.yasserapps.studio;
import java.io.*;import java.nio.*;import java.nio.charset.*;import java.util.*;import java.util.regex.*;import java.util.zip.*;import java.security.*;
public final class ApkEngine {
 static final long MAX_ENTRY=64L*1024*1024, MAX_TOTAL=2L*1024*1024*1024;
 public static final long MAX_INPUT_SCAN=4L*1024*1024*1024;
 static final long MAX_SCAN_TOTAL=8L*1024*1024*1024, MAX_SCAN_DEX=512L*1024*1024, RAM_DEX=16L*1024*1024;
 static final Pattern URL=Pattern.compile("https?://[^\\s\\\"<>\\\\]{3,400}",Pattern.CASE_INSENSITIVE);
 static final Pattern HINT=Pattern.compile("telegram|update available|don't show again|premium|تحديث|تيليجرام",Pattern.CASE_INSENSITIVE);
 public static class Result {
 public final ScanSignals signals=new ScanSignals(); public int entries,dex,dexScanned; public long largestDex; public final List<String> scanWarnings=new ArrayList<>();public long bytes;public String sha256="";public final Set<String> abis=new TreeSet<>(),findings=new TreeSet<>();public final List<String> assets=new ArrayList<>();
 public String report(){return "SHA-256: "+sha256+"\nالمعماريات: "+String.join(", ",abis)+"\nعدد الملفات: "+entries+"\nDEX: "+dexScanned+" / "+dex+"\n"+(scanWarnings.isEmpty()?"":"فحص جزئي:\n"+String.join("\n",scanWarnings)+"\n")+"الحجم غير المضغوط: "+bytes+" bytes\n\nروابط ومؤشرات (ليست دليلاً على وظيفة الكود):\n"+String.join("\n",findings)+"\n\nملفات نصية قابلة للتحرير:\n"+String.join("\n",assets)+"\n\n"+signals.report();}
 }
 static boolean textAsset(String n){return n.startsWith("assets/")&&n.toLowerCase(Locale.ROOT).matches(".*\\.(json|txt|html|css|js|xml|properties|yaml|yml|csv)$");}
 static void valid(ZipEntry e,Set<String> seen)throws IOException{String n=e.getName();if(n.startsWith("/")||n.contains("\\")||Arrays.asList(n.split("/",-1)).contains("..")||!seen.add(n)||e.getSize()<0)throw new IOException("Unsafe entry: "+n);}
 static long copy(InputStream in,OutputStream out,long limit)throws IOException{byte[] b=new byte[65536];long total=0;int n;while((n=in.read(b))!=-1){total+=n;if(total>limit)throw new IOException("Size limit exceeded");out.write(b,0,n);}return total;}
 static byte[] read(ZipFile z,ZipEntry e,long limit)throws IOException{long size=e.getSize();if(size<0||size>limit||size>Integer.MAX_VALUE-8)throw new IOException("Entry too large");byte[] data=new byte[(int)size];try(InputStream in=z.getInputStream(e)){int pos=0;while(pos<data.length){int n=in.read(data,pos,data.length-pos);if(n<=0)throw new IOException("Truncated ZIP entry");pos+=n;}if(in.read()!=-1)throw new IOException("ZIP entry size mismatch");return data;}}
 static String decode(byte[] b)throws CharacterCodingException{return StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(b)).toString();}
 static void add(Result r,String source,String s){r.signals.observe(source,s);if(r.findings.size()>=3000)return;Matcher m=URL.matcher(s);while(m.find()&&r.findings.size()<3000)r.findings.add(source+": "+m.group());if(HINT.matcher(s).find()&&s.length()<300)r.findings.add(source+": "+s.replace('\n',' '));}
 static void dex(Result r,String name,byte[] data)throws IOException{if(data.length<112||data[0]!='d'||data[1]!='e'||data[2]!='x'||data[3]!='\n')throw new IOException("Invalid DEX");ByteBuffer b=ByteBuffer.wrap(data).order(ByteOrder.LITTLE_ENDIAN);int count=b.getInt(56),off=b.getInt(60);if(count<0||count>4000000||off<0||(long)off+4L*count>data.length)throw new IOException("Invalid string table");for(int i=0;i<count;i++){int p=b.getInt(off+4*i);if(p<0||p>=data.length)continue;int k=0;while(p<data.length&&k++<5){if((data[p++]&128)==0)break;}int end=p;while(end<data.length&&data[end]!=0&&end-p<8192)end++;if(end<data.length&&data[end]==0)add(r,name,new String(data,p,end-p,StandardCharsets.UTF_8));}}
 public static String sha256(File f)throws IOException{try{MessageDigest md=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(f)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)md.update(b,0,n);}StringBuilder h=new StringBuilder();for(byte x:md.digest())h.append(String.format(Locale.ROOT,"%02x",x&255));return h.toString();}catch(NoSuchAlgorithmException e){throw new IOException(e);}}
 public static Result scan(File apk)throws IOException{Result r=new Result();r.sha256=sha256(apk);Set<String> seen=new HashSet<>();boolean manifest=false;try(ZipFile z=new ZipFile(apk)){Enumeration<? extends ZipEntry> en=z.entries();while(en.hasMoreElements()){ZipEntry e=en.nextElement();valid(e,seen);if(++r.entries>50000)throw new IOException("Too many entries");r.bytes+=e.getSize();if(r.bytes>MAX_SCAN_TOTAL)throw new IOException("Archive too large for scanning");String n=e.getName();if(n.equals("AndroidManifest.xml"))manifest=true;if(n.matches("lib/[^/]+/[^/]+\\.so"))r.abis.add(n.split("/")[1]);if(n.matches("classes([0-9]+)?\\.dex")){r.dex++;r.largestDex=Math.max(r.largestDex,e.getSize());if(e.getSize()>MAX_SCAN_DEX){r.scanWarnings.add(n+": يتجاوز حد تحليل DEX");}else if(e.getSize()<=RAM_DEX){dex(r,n,read(z,e,RAM_DEX));r.dexScanned++;}else{try{scanDexOnDisk(apk,z,e,r);r.dexScanned++;}catch(InterruptedIOException cancelled){throw cancelled;}catch(IOException err){r.scanWarnings.add(n+": تعذر الفحص عبر التخزين المؤقت: "+err.getMessage());}}}if(textAsset(n)&&e.getSize()<=2097152){try{String s=decode(read(z,e,2097152));r.assets.add(n);add(r,n,s);}catch(CharacterCodingException ignored){}}}}if(!manifest)throw new IOException("No AndroidManifest.xml");return r;}
 static void scanDexOnDisk(File apk,ZipFile z,ZipEntry e,Result r)throws IOException{
 File dir=apk.getAbsoluteFile().getParentFile();long free=dir.getUsableSpace();
 if(free>0&&free<e.getSize()+32L*1024*1024)throw new IOException("Insufficient temporary storage");
 File tmp=File.createTempFile("dex-inspect-",".tmp",dir);
 try{try(InputStream in=z.getInputStream(e);OutputStream out=new FileOutputStream(tmp)){if(copy(in,out,e.getSize())!=e.getSize())throw new IOException("Truncated DEX");}DiskDexScan.inspect(tmp,e.getName(),r);}finally{tmp.delete();}
 }
 public static String asset(File apk,String name)throws IOException{if(!textAsset(name))throw new IOException("Only text assets supported");try(ZipFile z=new ZipFile(apk)){ZipEntry e=z.getEntry(name);if(e==null)throw new IOException("Missing asset");return decode(read(z,e,2097152));}}
 public static void rebuild(File input,File output,String name,String oldText,String newText)throws IOException{if(input.getCanonicalFile().equals(output.getCanonicalFile())||oldText.isEmpty()||oldText.equals(newText))throw new IOException("Invalid replacement");Result checked=scan(input);if(checked.bytes>MAX_TOTAL||checked.largestDex>MAX_ENTRY||!checked.scanWarnings.isEmpty())throw new IOException("Archive exceeds verified editing scope");String original=asset(input,name);int p=original.indexOf(oldText);if(p<0||original.indexOf(oldText,p+1)>=0)throw new IOException("Exactly one match required");byte[] changed=(original.substring(0,p)+newText+original.substring(p+oldText.length())).getBytes(StandardCharsets.UTF_8);if(changed.length>2097152)throw new IOException("Edited asset too large");repack(input,output,name,changed);if(!asset(output,name).equals(new String(changed,StandardCharsets.UTF_8)))throw new IOException("Rebuild verification failed");}
 static boolean signingMetadata(String n){String u=n.toUpperCase(Locale.ROOT);return n.equals("stamp-cert-sha256")||u.equals("META-INF/MANIFEST.MF")||u.matches("META-INF/[^/]+\\.(SF|RSA|DSA|EC)");}
 static void repack(File input,File output,String name,byte[] changed)throws IOException{if(input.getCanonicalFile().equals(output.getCanonicalFile()))throw new IOException("Output must differ from input");Set<String> seen=new HashSet<>();boolean ok=false;try(ZipFile z=new ZipFile(input);ZipOutputStream out=new ZipOutputStream(new FileOutputStream(output))){Enumeration<? extends ZipEntry> en=z.entries();while(en.hasMoreElements()){ZipEntry e=en.nextElement();valid(e,seen);String n=e.getName();if(signingMetadata(n))continue;ZipEntry t=new ZipEntry(n);t.setMethod(e.getMethod());if(e.getMethod()==ZipEntry.STORED){if(n.equals(name)){CRC32 crc=new CRC32();crc.update(changed);t.setSize(changed.length);t.setCrc(crc.getValue());}else{t.setSize(e.getSize());t.setCrc(e.getCrc());}}out.putNextEntry(t);if(n.equals(name))out.write(changed);else if(!e.isDirectory())try(InputStream in=z.getInputStream(e)){copy(in,out,e.getSize());}out.closeEntry();}out.finish();ok=true;}finally{if(!ok)output.delete();}}
}